const { createHash } = require('node:crypto');
const delta = require('./firstresponse_patient_wrist_finish_delta.json');
const hash = source => createHash('sha256').update(source).digest('hex');
function revertPatientWristFinish(source) {
  if (hash(source) === delta.beforeSHA256) return source;
  if (hash(source) !== delta.afterSHA256) throw new Error('Patient wrist finish source does not match its exact refinement delta');
  for (const edit of [...delta.edits].reverse()) {
    if (source.split(edit.new).length !== 2) throw new Error('Patient wrist finish reversal is not unique: ' + (edit.name || 'source edit'));
    source = source.replace(edit.new, edit.old);
  }
  if (hash(source) !== delta.beforeSHA256) throw new Error('Patient wrist finish reversal did not recover fixed baseline');
  return source;
}
module.exports = { revertPatientWristFinish, delta };

